```sql
SELECT t1.customer_id, t1.name, COALESCE(SUM(CASE WHEN t2.type = 'charge' THEN t2.amount_cents END), 0) - COALESCE(SUM(CASE WHEN t2.type = 'refund' THEN t2.amount_cents END), 0) AS lifetime_value_cents FROM customers t1 LEFT JOIN payments t2 ON t2.customer_id = t1.customer_id GROUP BY t1.customer_id, t1.name ORDER BY lifetime_value_cents DESC LIMIT 10;
```

