import csv
import io

def parse_csv(text: str) -> list[list[str]]:
    sample = text[:1024]
    try:
        dialect = csv.Sniffer().sniff(sample, delimiters=",;\t")
    except csv.Error:
        class dialect(csv.excel):
            delimiter = ","
    rows = []
    for row in csv.reader(io.StringIO(text), dialect):
        if any(f.strip() for f in row):
            rows.append(row)
    return rows
