```python
def parse_csv(text: str) -> list[list[str]]:
    # detect delimiter on the first non-empty line, ties: ',' > ';' > '\t'
    delim = ","
    for line in text.split("\n"):
        if line.strip():
            tallies = ((line.count(","), ","), (line.count(";"), ";"),
                       (line.count("\t"), "\t"))
            top = max(t[0] for t in tallies)
            if top:
                delim = next(d for c, d in tallies if c == top)
            break

    out: list[list[str]] = []
    cur: list[str] = []
    piece = ""
    quoted_piece = False
    quoting = False
    seen_any = False

    def flush_field():
        nonlocal piece, quoted_piece
        cur.append(piece if quoted_piece else piece.strip(" \t"))
        piece = ""
        quoted_piece = False

    def flush_row():
        nonlocal cur, seen_any
        flush_field()
        if len(cur) > 1 or any(cur):
            out.append(cur)
        cur = []
        seen_any = False

    idx = 0
    while idx < len(text):
        ch = text[idx]
        if quoting:
            if ch == '"':
                if text[idx + 1:idx + 2] == '"':
                    piece += '"'
                    idx += 2
                    continue
                quoting = False
            else:
                piece += ch
            idx += 1
            continue
        if ch == '"' and piece.strip(" \t") == "":
            piece = ""
            quoting = True
            quoted_piece = True
            seen_any = True
        elif ch == delim:
            flush_field()
            seen_any = True
        elif ch == "\n":
            if seen_any or piece.strip(" \t"):
                flush_row()
            else:
                piece = ""
        elif ch == "\r":
            pass
        elif quoted_piece and ch in " \t":
            pass
        else:
            piece += ch
            seen_any = seen_any or ch not in " \t"
        idx += 1
    if seen_any or piece.strip(" \t"):
        flush_row()
    return out
